async fn connection_timeout[T](deadline : Int64, run : async () -> T) -> T {
  let remaining = deadline - @env.now()
  if remaining <= 0 { raise AdapterError("SSH and relay readiness timed out after 60 seconds") }
  @async.with_timeout(remaining.to_int(), run) catch {
    @async.TimeoutError => {
      save_diagnostic("connection-readiness", "timeout", error_type="readiness_timeout")
      raise AdapterError("SSH and relay readiness timed out after 60 seconds; recovery continues while the workspace remains")
    }
  }
}

///|
async fn wait_tunnel(directory : String, deadline : Int64) -> Unit {
  let started = @env.now()
  progress_message("ssh-tunnel: connecting…")
  errdefer progress_message("ssh-tunnel: failed (" + progress_timing(started) + ")")
  @fs.write_file(directory + "/probe-request", "", permission=0o600)
  connection_timeout(deadline, async fn() {
    while true {
      if @fs.exists(directory + "/status.json") {
        let status = @json.parse(@fs.read_file(directory + "/status.json").text())
        match field(status, "status") {
          Some(Json::String("ownership-error")) => raise AdapterError("Tunnel workspace ownership changed")
          Some(Json::String("workspace-stopped")) => raise AdapterError("Tunnel workspace stopped")
          Some(Json::String("unsupported")) => raise AdapterError("Devsy /ready is unsupported; upgrade Devsy to a version supporting relay readiness")
          Some(Json::String("connected")) if !@fs.exists(directory + "/probe-request") && worker_alive(directory) => {
            let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
            try { check_tunnel(saved, directory); return } catch { _ => () }
          }
          _ => ()
        }
      }
      @async.sleep(100)
    }
  })
  progress_message("ssh-tunnel: connected (" + progress_timing(started) + ")")
}

