pub async fn tunnel_worker(directory : String) -> Unit {
  let lock = @fs.open(directory + "/worker.lock", mode=ReadWrite, create_mode=OpenOrCreate, permission=0o600)
  defer lock.close()
  if !lock.try_lock(Exclusive) { return }
  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
  validate_state(state)
  let forwarding = match field(state, "localPort") {
    Some(Json::Number(value, ..)) => ["-L", "127.0.0.1:\\{value.to_int()}:127.0.0.1:47121"]
    None if field(state, "connection") == Some(Json::string("ssh")) => []
    _ => raise AdapterError("Missing tunnel port")
  }
  let enabled = directory + "/enabled"
  let mut adopted = try { check_tunnel(state, directory); true } catch { _ => false }
  let mut attempt = 0
  defer @async.protect_from_cancel(async fn() { stop_tunnel_master(state, directory) })
  while @fs.exists(enabled) {
    tunnel_status(directory, "connecting")
    git_relay_status(directory, "pending")
    let mut terminal = false
    @async.with_task_group(async fn(group) {
      group.spawn_bg(no_wait=true, async fn() {
        while @fs.exists(enabled) { @async.sleep(100) }
        group.cancel()
      })
      guard worker_workspace(state, directory) is Some(current) && field(current, "uid") == field(state, "workspaceUid") else {
        if @fs.exists(enabled) { @fs.remove(enabled) }
        terminal = true
        tunnel_status(directory, "ownership-error")
        return
      }
      if field(current, "running") != Some(Json::boolean(true)) {
        terminal = true
        tunnel_status(directory, "workspace-stopped")
        return
      }
      @fs.mkdir(required(state, "socketDirectory"), permission=0o700, allow_exist=true)
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let (errors, stderr) = @process.read_from_process()
      defer errors.close()
      let classified = group.spawn(async fn() { tunnel_errors(errors) }, no_wait=true)
      let child = if adopted {
        save_diagnostic("orca-tunnel", "adopted", tunnel_directory=directory)
        None
      } else {
        Some(@process.spawn(
          group, "ssh",
          ssh_args(state, lease=required(state, "socketDirectory") + "/primary-proxy.lock") +
          ["-M", "-S", control_socket(state, directory), "-N", "-o", "ExitOnForwardFailure=yes", "-o", "ServerAliveInterval=10", "-o", "ServerAliveCountMax=3"] + forwarding,
          stdin=@process.redirect_from_file("/dev/null"), stdout=sink, stderr~, no_wait=true,
        ))
      }
      adopted = false
      let git_enabled = @async.with_timeout(10000, async fn() { git_forwarding_enabled(state) })
      let mut next_probe = @env.now()
      let mut next_check = @env.now()
      let mut failures = 0
      let mut connected = false
      while @fs.exists(enabled) {
        if child is Some(child) && child.try_wait() is Some(code) {
          save_diagnostic("orca-tunnel", "disconnected", exit_code=code,
            error_type=@async.with_timeout(1000, async fn() { classified.wait() }) catch { _ => "process_exit" }, tunnel_directory=directory)
          break
        }
        if @env.now() >= next_check {
          let alive = try { check_tunnel(state, directory); true } catch { _ => false }
          if !alive {
            if connected || child is None { break }
            @async.sleep(100)
            continue
          }
          next_check = @env.now() + 1000
        }
        if @env.now() >= next_probe || @fs.exists(directory + "/probe-request") {
          match relay_readiness(state, directory, git_enabled) {
            Ready => {
              failures = 0
              attempt = 0
              if !connected {
                connected = true
                git_relay_status(directory, if git_enabled { "ready" } else { "disabled" })
                tunnel_status(directory, "connected")
              }
              if @fs.exists(directory + "/probe-request") { @fs.remove(directory + "/probe-request") }
              next_probe = @env.now() + 10000
            }
            Unsupported => {
              terminal = true
              tunnel_status(directory, "unsupported")
              break
            }
            Retry(reason) => {
              failures += 1
              connected = false
              git_relay_status(directory, "unavailable")
              tunnel_status(directory, "checking")
              save_diagnostic("relay-recovery", "failed", attempt=failures, error_type=reason, tunnel_directory=directory)
              if failures >= 2 { break }
              continue
            }
          }
        }
        @async.sleep(100)
      }
    }) catch {
      _ => if @fs.exists(enabled) { save_diagnostic("orca-tunnel", "process-error", tunnel_directory=directory) }
    }
    stop_tunnel_master(state, directory, verify=true)
    if terminal { return }
    if @fs.exists(enabled) {
      tunnel_status(directory, "disconnected")
      attempt = if attempt < 6 { attempt + 1 } else { 6 }
      let delay = if attempt < 6 { 500 * (1 << attempt) } else { 30000 }
      save_diagnostic("orca-tunnel", "retry", attempt~, retry_delay_ms=delay, tunnel_directory=directory)
      for elapsed = 0; elapsed < delay && @fs.exists(enabled); elapsed = elapsed + 100 { @async.sleep(100) }
    }
  }
  tunnel_status(directory, "stopped")
}

